import json
import itertools
import sympy as sp

# Decode each ReLU coordinate as a threshold of the preceding Boolean
# coordinates, using its affine coefficients rather than network evaluations.
W = W
x = sp.symbols("x0:10")
prev = list(x)

def threshold_expr(coeffs, bias, vars_):
    # Rewrite negative coefficients using complemented literals. The result
    # is a monotone weighted threshold with an adjusted constant.
    lits, weights = [], []
    base = int(round(float(bias)))
    for c, v in zip(coeffs, vars_):
        c = int(round(float(c)))
        if c > 0:
            lits.append(v)
            weights.append(c)
        elif c < 0:
            lits.append(sp.Not(v))
            weights.append(-c)
            base += c
    need = 1 - base  # sum(weights*lits) >= need
    if need <= 0:
        return sp.true
    if need > sum(weights):
        return sp.false

    # Coefficient-derived minimal winning coalitions.
    winners = []
    for size in range(1, len(weights) + 1):
        for ids in itertools.combinations(range(len(weights)), size):
            if sum(weights[i] for i in ids) < need:
                continue
            if any(set(old).issubset(ids) for old in winners):
                continue
            winners.append(ids)
    return sp.Or(*[sp.And(*[lits[i] for i in ids]) for ids in winners])

for layer in range(4):
    mat = W[f"target.w{layer}"]
    bias = W[f"target.b{layer}"]
    rows = []
    for r in range(34):
        row = mat[r]
        coeffs = [float(v) for v in row]
        # Ignore zero-weight coordinates; retain their corresponding formulas.
        active = [(c, prev[i]) for i, c in enumerate(coeffs) if c != 0]
        expr = threshold_expr([c for c, _ in active], float(bias[r]),
                              [v for _, v in active])
        rows.append(sp.simplify_logic(expr, form="dnf"))
    prev = rows

