                                 sp.And(q, sp.Not(r)),
                                 sp.And(p, q)), form="dnf")

def to_ast(e):
    if e == sp.true:
        return {"op": "or", "left": {"op": "input", "index": 0},
                "right": {"op": "not", "arg": {"op": "input", "index": 0}}}
    if e == sp.false:
        return {"op": "and", "left": {"op": "input", "index": 0},
                "right": {"op": "not", "arg": {"op": "input", "index": 0}}}
    if e in x:
        return {"op": "input", "index": int(str(e)[1:])}
    if e.func == sp.Not:
        return {"op": "not", "arg": to_ast(e.args[0])}
    if e.func in (sp.And, sp.Or, sp.Xor):
        op = {sp.And: "and", sp.Or: "or", sp.Xor: "xor"}[e.func]
        args = [to_ast(a) for a in e.args]
        out = args[0]
        for a in args[1:]:
            out = {"op": op, "left": out, "right": a}
        return out
    raise ValueError(f"Unsupported expression: {e}")

